  async function initDiagram(shell) {
    const wrap = shell.querySelector('.mermaid-wrap');
    const viewport = shell.querySelector('.mermaid-viewport');
    const canvas = shell.querySelector('.mermaid-canvas');
    const sourceEl = shell.querySelector('.mermaid-canvas');
    const label = shell.querySelector('.zoom-label');
    const controls = shell.querySelector('.zoom-controls');

    if (!wrap || !viewport || !canvas || !label || !sourceEl) {
      console.error('Missing elements');
      return;
    }

    let zoom = 1, panX = 0, panY = 0, svgW = 0, svgH = 0;

    function updateTransform() {
      canvas.style.transform = `translate(${panX}px, ${panY}px)`;
      canvas.querySelector('svg')?.setAttribute('width', svgW * zoom);
      canvas.querySelector('svg')?.setAttribute('height', svgH * zoom);
      label.textContent = `${Math.round(zoom * 100)}%`;
    }

    function fitDiagram() {
      const vw = viewport.clientWidth;
      const vh = viewport.clientHeight;
      if (svgW === 0 || svgH === 0) return;
      const scaleX = (vw - 40) / svgW;
      const scaleY = (vh - 40) / svgH;
      zoom = Math.min(scaleX, scaleY, 2.5);
      panX = (vw - svgW * zoom) / 2;
      panY = (vh - svgH * zoom) / 2;
      updateTransform();
    }

    try {
      const code = sourceEl.textContent.trim();
      if (!code) { label.textContent = 'Error: empty'; return; }
      const id = 'diagram-' + Date.now() + '-' + Math.random().toString(36).slice(2, 8);
      const { svg } = await mermaid.render(id, code);
      canvas.innerHTML = svg;
      const svgNode = canvas.querySelector('svg');
      if (svgNode) {
        svgW = svgNode.viewBox?.baseVal?.width || svgNode.getBoundingClientRect().width || 1000;
        svgH = svgNode.viewBox?.baseVal?.height || svgNode.getBoundingClientRect().height || 800;
      }
      fitDiagram();
    } catch (err) {
      console.error('Mermaid error:', err);
      label.textContent = 'Error: ' + (err.message || 'render failed');
      return;
    }

    // Controls
    controls.querySelector('[data-action="zoom-in"]').onclick = () => {
      zoom = Math.min(zoom * 1.25, 5); updateTransform();
    };
    controls.querySelector('[data-action="zoom-out"]').onclick = () => {
      zoom = Math.max(zoom / 1.25, 0.2); updateTransform();
    };
    controls.querySelector('[data-action="zoom-fit"]').onclick = fitDiagram;
    controls.querySelector('[data-action="zoom-expand"]').onclick = () => {
      const svgNode = canvas.querySelector('svg');
      if (svgNode) {
        const data = new XMLSerializer().serializeToString(svgNode);
        const blob = new Blob(['<!DOCTYPE html><html><body style="margin:0;background:#fff">' + data + '</body></html>'], {type: 'text/html'});
        window.open(URL.createObjectURL(blob), '_blank');
