    };

    // Scroll zoom
    viewport.addEventListener('wheel', (e) => {
      e.preventDefault();
      const delta = e.deltaY > 0 ? 0.9 : 1.1;
      zoom = Math.max(0.2, Math.min(5, zoom * delta));
      updateTransform();
    }, { passive: false });

    // Panning
    let dragStart = null, dragPanStart = null;
    viewport.addEventListener('mousedown', (e) => {
      if (e.button === 0) {
        dragStart = { x: e.clientX, y: e.clientY };
        dragPanStart = { x: panX, y: panY };
        activeDrag = {
          onMove: (ev) => {
            panX = dragPanStart.x + (ev.clientX - dragStart.x);
            panY = dragPanStart.y + (ev.clientY - dragStart.y);
            updateTransform();
          },
          onEnd: () => {}
        };
      }
    });

    // Double-click to fit
    viewport.addEventListener('dblclick', fitDiagram);
  }

