      direction TB
      svc-shipping["Shipping Service\nConsumer\nExp-Backoff · 4 retries"]
      svc-notification["Notification Service\nConsumer\nFixed-Interval · 2 retries"]
      svc-analytics["Analytics Service\nConsumer | Best-Effort\nNo Retry"]
    end

    subgraph dlq["DEAD LETTER QUEUES"]
      direction LR
      dlq.payments[("dlq.payments\n3p · rf3")]
      dlq.inventory[("dlq.inventory\n3p · rf3")]
      dlq.shipping[("dlq.shipping\n3p · rf3")]
      dlq.notification[("dlq.notification\n2p · rf3")]
    end

    subgraph schema_box[" "]
      schema-registry["Schema Registry\nAVRO Validation\nsync-http"]
    end

    subgraph monitoring["MONITORING & ALERTING"]
      direction LR
      prometheus["Prometheus\n10-30s scrape"]
      grafana["Grafana\nEDA Dashboard"]
      alertmanager["Alertmanager"]
      pagerduty["PagerDuty\nCritical"]
      slack["Slack\nWarnings"]
    end

    %% === PRODUCE (green) ===
    svc-order -->|"avro"| orders.created
    svc-order -->|"avro"| orders.updated
    svc-payment -->|"avro"| payments.completed
    svc-payment -->|"avro"| payments.failed
    svc-inventory -->|"avro"| inventory.reserved
    svc-inventory -->|"avro"| inventory.released
    svc-shipping -->|"avro"| shipping.dispatched

    %% === CONSUME (blue) ===
    orders.created -->|"payment-cg"| svc-payment
    orders.created -->|"inventory-cg"| svc-inventory
    orders.created -->|"notif-cg"| svc-notification
    orders.created -->|"analytics-cg"| svc-analytics
    orders.updated -->|"analytics-cg"| svc-analytics
    payments.completed -->|"shipping-cg"| svc-shipping
    payments.completed -->|"notif-cg"| svc-notification
    payments.completed -->|"analytics-cg"| svc-analytics
    payments.failed -->|"inventory-cg"| svc-inventory
    payments.failed -->|"notif-cg"| svc-notification
    payments.failed -->|"analytics-cg"| svc-analytics
    inventory.reserved -->|"shipping-cg"| svc-shipping
    inventory.reserved -->|"analytics-cg"| svc-analytics
    inventory.released -->|"analytics-cg"| svc-analytics
    shipping.dispatched -->|"notif-cg"| svc-notification
    shipping.dispatched -->|"analytics-cg"| svc-analytics

    %% === DLQ (red dashed) ===
    svc-payment -.->|"max-retries"| dlq.payments
    svc-inventory -.->|"max-retries"| dlq.inventory
    svc-shipping -.->|"max-retries"| dlq.shipping
    svc-notification -.->|"max-retries"| dlq.notification

    %% === SCHEMA REGISTRY (purple dotted bidirectional) ===
    svc-order <==>|"schema-lookup"| schema-registry
    svc-payment <==>|"schema-lookup"| schema-registry
    svc-inventory <==>|"schema-lookup"| schema-registry
    svc-shipping <==>|"schema-lookup"| schema-registry
    svc-notification <==>|"schema-lookup"| schema-registry
    svc-analytics <==>|"schema-lookup"| schema-registry

    %% === MONITORING ===
    svc-order --> prometheus
    svc-payment --> prometheus
    svc-inventory --> prometheus
    svc-shipping --> prometheus
    svc-notification --> prometheus
    svc-analytics --> prometheus
    schema-registry --> prometheus

    prometheus --> grafana
    prometheus -->|"lag_critical\ndlq_rate_high\nhealth_down"| alertmanager
    alertmanager -->|"critical"| pagerduty
    alertmanager -->|"warning"| slack

    %% === STYLING ===
    classDef producer fill:#d4edda,stroke:#16a34a,stroke-width:2px,color:#1a3d2a
    classDef producerConsumer fill:#fff3cd,stroke:#b45309,stroke-width:2px,color:#4a3000
    classDef consumer fill:#cfe2ff,stroke:#2563eb,stroke-width:2px,color:#1a2740
    classDef topic fill:#e5e7eb,stroke:#4b5563,stroke-width:1.5px,color:#1f2937
    classDef dlq fill:#f8d7da,stroke:#dc2626,stroke-width:2px,stroke-dasharray:4 3,color:#991b1b
    classDef schema fill:#e9d5ff,stroke:#9333ea,stroke-width:2px,color:#581c87
    classDef monitor fill:#e2e8f0,stroke:#64748b,stroke-width:1.5px,color:#1e293b
    classDef alert fill:#ffcdd2,stroke:#c62828,stroke-width:1.5px,color:#7f1d1d

    class svc-order producer
    class svc-payment,svc-inventory producerConsumer
    class svc-shipping,svc-notification,svc-analytics consumer
    class orders.created,orders.updated,payments.completed,payments.failed,inventory.reserved,inventory.released,shipping.dispatched topic
    class dlq.payments,dlq.inventory,dlq.shipping,dlq.notification dlq
    class schema-registry schema
    class prometheus,grafana,slack monitor
    class alertmanager,pagerduty alert
  `;

  try {
    const { svg } = await mermaid.render('arch-diagram', code);
    document.getElementById('diagram').innerHTML = svg;
    const svgEl = document.getElementById('diagram').querySelector('svg');
    if (svgEl) {
      const vb = svgEl.getAttribute('viewBox');
      if (vb) {
        const [, , w, h] = vb.split(' ').map(Number);
        svgEl.setAttribute('width', Math.max(w, 1800));
        svgEl.removeAttribute('height');
        svgEl.style.maxWidth = '100%';
        svgEl.style.height = 'auto';
      }
    }
  } catch (err) {
    document.getElementById('diagram').innerHTML =
      '<p style="color:red;">Mermaid error: ' + (err.message || 'unknown') + '</p>';
    console.error(err);
  }
</script>

</body>
</html>
